import React, { useState } from "react";

const UploadSection = ({ setResults }) => {
  const [file, setFile] = useState(null);
  const [model, setModel] = useState("");

  const handleSubmit = () => {
    if (!file || !model) {
      alert("Please upload a file and select a model");
      return;
    }

    alert("Backend not connected yet. Frontend working!");
  };

  return (
    <div style={{ background: "white", padding: "25px", marginTop: "40px", borderRadius: "10px" }}>
      <h2>Upload Dataset & Choose Model</h2>

      <input
        type="file"
        accept=".csv"
        onChange={(e) => setFile(e.target.files[0])}
        style={{ marginTop: "20px", marginBottom: "10px" }}
      />

      <select
        onChange={(e) => setModel(e.target.value)}
        style={{ padding: "8px", marginTop: "10px", width: "200px" }}
      >
        <option value="">Select Model</option>
        <option value="logistic_regression">Logistic Regression</option>
        <option value="random_forest">Random Forest</option>
        <option value="xgboost">XGBoost</option>
      </select>

      <br /><br />

      <button
        onClick={handleSubmit}
        style={{ background: "blue", color: "white", padding: "10px 20px", borderRadius: "5px" }}
      >
        Begin Prediction
      </button>
    </div>
  );
};

export default UploadSection;
